// Map Plausible stats → analytics_events rows
// Refs: docs/specs/devrel-analytics-stack.md Decision 4
const results = $json.results || [];
const occurredAt = new Date().toISOString();
const rows = [];

for (const entry of results) {
  const page = entry.page || entry.dimensions?.[0] || 'unknown';
  const contentId = `plausible:${page.replace(/^https?:\/\/[^/]+/, '')}`;

  if (entry.metrics?.pageviews || entry.pageviews) {
    rows.push({
      platform: 'plausible',
      content_id: contentId,
      event_type: 'view',
      occurred_at: occurredAt,
      metric_value: entry.metrics?.pageviews ?? entry.pageviews ?? 0,
      metadata: JSON.stringify({ page, bounce_rate: entry.metrics?.bounce_rate ?? entry.bounce_rate })
    });
  }
  if (entry.metrics?.visitors || entry.visitors) {
    rows.push({
      platform: 'plausible',
      content_id: contentId,
      event_type: 'impression',
      occurred_at: occurredAt,
      metric_value: entry.metrics?.visitors ?? entry.visitors ?? 0,
      metadata: JSON.stringify({ page })
    });
  }
}

return rows.map(row => ({ json: row }));
